units.exampleCode:
#include <iostream>
using namespace std;

int main() {
    int n = 12321;
    int temp = n, rev = 0;
    while (temp > 0) {
        rev = rev * 10 + temp % 10;
        temp /= 10;
    }
    if (rev == n) {
        cout << n << " 是回文数" << endl;
    } else {
        cout << n << " 不是回文数" << endl;
    }
    return 0;
}

practice.expectedIdea:
int n;
cin >> n;
int temp = n, rev = 0;
while (temp > 0) {
    rev = rev * 10 + temp % 10;
    temp /= 10;
}
if (rev == n) cout << "Yes" << endl;
else cout << "No" << endl;

