using namespace std;

int main() {
    char c = '7';
    int val = c - '0';
    cout << c << " -> " << val << endl;
    string s = "1234";
    int sum = 0;
    for (int i = 0; i < s.length(); i++) {
        sum += s[i] - '0';
    }
    cout << "数位和: " << sum << endl;
    return 0;
}

