#include <iostream>
using namespace std;

int main() {
    int val = 7;
    char c = val + '0';
    cout << val << " -> '" << c << "'" << endl;
    int n = 42;
    string result = "";
    while (n > 0) {
        result = (char)(n % 10 + '0') + result;
        n /= 10;
    }
    cout << "结果: " << result << endl;
    return 0;
}

practice.expectedIdea:
int n;
cin >> n;
char c = n + '0';
cout << c << endl;

